// Reverse-engineer what pre-money "fair value" F yields 6.1% under various
// contribution-credit assumptions. Formula: (0.18F + cI)/(F + 1,500,000) = target
const solve = (cI, target, total=1500000) => (target*(total) - 0.18*0*0 + (target*0) + target*0, (target*total - 0 + 0) );
function solveF(cI, target, totalNew=1500000){
  // (0.18F + cI) = target*(F + totalNew)  ->  F(0.18-target) = target*totalNew - cI
  return (target*totalNew - cI)/(0.18-target);
}
const rows = [
  ['A. pro rata: Bram 1,230,000 + Imani 270,000 credited', 270000],
  ['B. only Bram funds own share (1,230,000); Imani credited 0', 0],
  ['C. only Imani 270,000 credited (Bram not credited)', 270000],
];
const out = [];
for (const [label,cI] of rows) {
  for (const t of [0.061, 0.1489]) {
    const F = solveF(cI,t);
    out.push([label, 'target '+(t*100).toFixed(2)+'%', cI, F>0 ? '$'+Math.round(F).toLocaleString('en-US') : 'no positive F (impossible)']);
  }
}
// Recompute the dilution as a spreadsheet check for the Manager's stated $7.2M:
const F=7200000;
const table = [
  {party:'Bram', pre:0.82*F, funded:1230000},
  {party:'Imani', pre:0.18*F, funded:270000},
];
const post = F + 1500000;
const recomputed = table.map(r=>({party:r.party, pre_pct: r.pre/F, post_pct:(r.pre+r.funded)/post}));

// Offer vs each valuation, both percentages
const vals = {'Manager FV $7.2M':7200000,'Broker equity $9.8M':9800000,'Book equity $3.1M':3100000};
const matrix = [];
for (const [k,v] of Object.entries(vals))
  for (const p of [0.18,0.061])
    matrix.push([k,(p*100)+'%', '$'+Math.round(p*v).toLocaleString('en-US')]);

// Section 5.4 disclosure exposure: fees above $50k/yr that were never disclosed in writing
const fees=[180000,195000,210000,225000,240000];
const undisc = fees.reduce((s,a)=>s+a,0);

// Property mgmt 6% of gross rents: cannot compute — gross rents not in file.
JSON.stringify({solve_6_1pct: out, recomputed_at_7_2M: recomputed.map(r=>[r.party, (r.pre_pct*100).toFixed(1)+'%', (r.post_pct*100).toFixed(2)+'%']),
 matrix, undisclosed_fees_total: undisc, gross_rents: 'NOT IN FILE — cannot quantify 6% property mgmt fee'}, null, 1)

